import{_ as r,o as t,c as e,ag as l}from"./chunks/framework.DXGyWiRo.js";const _=JSON.parse('{"title":"Правила допустимого использования (AUP)","description":"","frontmatter":{},"headers":[],"relativePath":"aup.md","filePath":"aup.md","lastUpdated":null}'),o={name:"aup.md"};function i(n,a,s,h,p,d){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="правила-допустимого-использования-aup" tabindex="-1">Правила допустимого использования (AUP) <a class="header-anchor" href="#правила-допустимого-использования-aup" aria-label="Permalink to &quot;Правила допустимого использования (AUP)&quot;">​</a></h1><h2 id="антиспам-политика" tabindex="-1">Антиспам-политика <a class="header-anchor" href="#антиспам-политика" aria-label="Permalink to &quot;Антиспам-политика&quot;">​</a></h2><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p><p><em>Редакция от 21 апреля 2026 г.</em></p><hr><p>Настоящие Правила допустимого использования (Acceptable Use Policy, далее — <strong>Правила</strong>) устанавливают требования к использованию сервиса GoSMS и являются неотъемлемой частью <a href="/public-offer">Публичной оферты</a> и <a href="/user-agreement">Пользовательского соглашения</a>.</p><h2 id="_1-статус-сервиса" tabindex="-1">1. Статус сервиса <a class="header-anchor" href="#_1-статус-сервиса" aria-label="Permalink to &quot;1. Статус сервиса&quot;">​</a></h2><p>1.1. GoSMS — техническое решение для автоматизированного управления Android-устройствами в части отправки и приёма SMS-сообщений.</p><p>1.2. <strong>GoSMS не является SMS-шлюзом.</strong> Все SMS-сообщения отправляются непосредственно SIM-картой устройства Пользователя. Отправителем является сам Пользователь, а не Администрация.</p><p>1.3. Пользователь несёт <strong>полную ответственность</strong> за содержание отправляемых сообщений и за соблюдение требований законодательства, включая ФЗ-38 «О рекламе», ФЗ-149 «Об информации», ФЗ-152 «О персональных данных» и иных применимых норм.</p><h2 id="_2-запрещенные-виды-использования" tabindex="-1">2. Запрещённые виды использования <a class="header-anchor" href="#_2-запрещенные-виды-использования" aria-label="Permalink to &quot;2. Запрещённые виды использования&quot;">​</a></h2><p>Пользователю <strong>запрещается</strong> использовать Сервис для:</p><h3 id="_2-1-незаконныи-контент" tabindex="-1">2.1. Незаконный контент <a class="header-anchor" href="#_2-1-незаконныи-контент" aria-label="Permalink to &quot;2.1. Незаконный контент&quot;">​</a></h3><ul><li>рассылки незапрошенных коммерческих сообщений (спама) без наличия у получателей явного, документально подтверждённого согласия (ст. 18 ФЗ-38);</li><li>распространения материалов, пропагандирующих насилие, экстремизм, терроризм, включённых в федеральный список запрещённых организаций;</li><li>распространения порнографических материалов;</li><li>распространения материалов, нарушающих права несовершеннолетних;</li><li>распространения сведений, составляющих государственную, коммерческую, банковскую или иную охраняемую законом тайну.</li></ul><h3 id="_2-2-мошенничество-и-фишинг" tabindex="-1">2.2. Мошенничество и фишинг <a class="header-anchor" href="#_2-2-мошенничество-и-фишинг" aria-label="Permalink to &quot;2.2. Мошенничество и фишинг&quot;">​</a></h3><ul><li>отправки сообщений с ложным указанием отправителя (подмена ID отправителя);</li><li>реализации фишинговых схем и мошеннических действий;</li><li>сбора персональных данных получателей без их ведома и согласия;</li><li>отправки сообщений с вредоносными ссылками или вложениями.</li></ul><h3 id="_2-3-нарушение-прав-третьих-лиц" tabindex="-1">2.3. Нарушение прав третьих лиц <a class="header-anchor" href="#_2-3-нарушение-прав-третьих-лиц" aria-label="Permalink to &quot;2.3. Нарушение прав третьих лиц&quot;">​</a></h3><ul><li>нарушения авторских прав, товарных знаков или иных прав интеллектуальной собственности;</li><li>нарушения права на неприкосновенность частной жизни и персональных данных получателей;</li><li>использования баз данных, приобретённых у третьих лиц без подтверждения законности их сбора и наличия согласий на рассылку.</li></ul><h3 id="_2-4-нарушение-функционирования" tabindex="-1">2.4. Нарушение функционирования <a class="header-anchor" href="#_2-4-нарушение-функционирования" aria-label="Permalink to &quot;2.4. Нарушение функционирования&quot;">​</a></h3><ul><li>попыток обойти технические ограничения Сервиса;</li><li>перегрузки инфраструктуры Сервиса сверх технических ограничений тарифа;</li><li>несанкционированного доступа к данным других пользователей.</li></ul><h2 id="_3-требования-к-рассылкам" tabindex="-1">3. Требования к рассылкам <a class="header-anchor" href="#_3-требования-к-рассылкам" aria-label="Permalink to &quot;3. Требования к рассылкам&quot;">​</a></h2><p>При осуществлении рассылок Пользователь обязан:</p><p>3.1. <strong>Согласие получателей.</strong> Располагать явным, свободным, конкретным и документально подтверждённым согласием каждого получателя на получение сообщений данного вида (ст. 18 ФЗ-38). Согласие должно быть получено до отправки первого сообщения.</p><p>3.2. <strong>Идентификация отправителя.</strong> Чётко идентифицировать себя в каждом сообщении, указывая наименование, телефон или email для ответа.</p><p>3.3. <strong>Возможность отписки.</strong> Включать в рекламные сообщения чёткую инструкцию по отказу от рассылки и немедленно выполнять запросы об отписке.</p><p>3.4. <strong>Законность базы данных.</strong> Использовать только контактные базы данных, собранные законными методами:</p><ul><li>прямое согласие пользователей через формы сайта;</li><li>согласие при покупке товара или услуги (только для информации о схожих товарах, п. 15 ст. 18 ФЗ-38);</li><li>иные законные основания.</li></ul><p><strong>Запрещается</strong> использование купленных, арендованных, «спарсенных» или иным образом неправомерно полученных баз данных.</p><p>3.5. <strong>Частота.</strong> Не превышать разумную частоту рассылок, не вызывающую неудобства для получателей.</p><h2 id="_4-мониторинг-и-ответственность" tabindex="-1">4. Мониторинг и ответственность <a class="header-anchor" href="#_4-мониторинг-и-ответственность" aria-label="Permalink to &quot;4. Мониторинг и ответственность&quot;">​</a></h2><p>4.1. Администрация <strong>не осуществляет предварительную модерацию</strong> содержимого SMS-сообщений.</p><p>4.2. Администрация вправе в любое время проверить соответствие действий Пользователя настоящим Правилам при наличии обоснованных жалоб от третьих лиц или признаков нарушений.</p><p>4.3. Администрация вправе запросить у Пользователя документальное подтверждение наличия согласий получателей. При непредставлении документов в течение <strong>5 (пяти) рабочих дней</strong> Администрация вправе применить меры, предусмотренные разд. 5.</p><h2 id="_5-последствия-нарушении" tabindex="-1">5. Последствия нарушений <a class="header-anchor" href="#_5-последствия-нарушении" aria-label="Permalink to &quot;5. Последствия нарушений&quot;">​</a></h2><p>При нарушении настоящих Правил Администрация вправе применить следующие меры:</p><table tabindex="0"><thead><tr><th>Мера</th><th>Условие применения</th></tr></thead><tbody><tr><td>Предупреждение</td><td>Первичное или незначительное нарушение</td></tr><tr><td>Временная приостановка рассылок</td><td>Повторное нарушение или жалобы получателей</td></tr><tr><td>Блокировка учётной записи</td><td>Систематические нарушения или грубое нарушение</td></tr><tr><td>Расторжение договора</td><td>Нарушения, повлёкшие ущерб третьим лицам или правовую ответственность</td></tr><tr><td>Передача данных в правоохранительные органы</td><td>Признаки уголовно наказуемых деяний</td></tr></tbody></table><p>5.1. Меры могут применяться без предварительного уведомления при явном и грубом нарушении Правил.</p><p>5.2. Пользователь возмещает Администрации все убытки, штрафы и санкции, возникшие в связи с нарушением им настоящих Правил, ФЗ-38 и иного применимого законодательства.</p><h2 id="_6-ответственность-за-жалобы" tabindex="-1">6. Ответственность за жалобы <a class="header-anchor" href="#_6-ответственность-за-жалобы" aria-label="Permalink to &quot;6. Ответственность за жалобы&quot;">​</a></h2><p>6.1. При получении жалоб от получателей сообщений Пользователя — Администрация уведомляет Пользователя и вправе потребовать предоставления доказательств наличия согласий.</p><p>6.2. При подтверждении нарушений Администрация вправе применить меры согласно разд. 5.</p><p>6.3. Пользователь обязан самостоятельно урегулировать жалобы получателей, в том числе обеспечить их немедленную отписку.</p><h2 id="_7-сообщение-о-нарушениях" tabindex="-1">7. Сообщение о нарушениях <a class="header-anchor" href="#_7-сообщение-о-нарушениях" aria-label="Permalink to &quot;7. Сообщение о нарушениях&quot;">​</a></h2><p>Для сообщения о нарушениях (жалоба на спам, незаконные рассылки):</p><p><strong>Email:</strong> <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a><br><strong>Тема письма:</strong> «Жалоба на рассылку»</p><p>Укажите в сообщении: дату, текст сообщения, номер отправителя. Мы рассматриваем жалобы в течение <strong>5 рабочих дней</strong>.</p><h2 id="_8-применимое-законодательство" tabindex="-1">8. Применимое законодательство <a class="header-anchor" href="#_8-применимое-законодательство" aria-label="Permalink to &quot;8. Применимое законодательство&quot;">​</a></h2><p>Настоящие Правила разработаны с учётом требований:</p><ul><li>Федерального закона от 13.03.2006 № 38-ФЗ «О рекламе»</li><li>Федерального закона от 27.07.2006 № 152-ФЗ «О персональных данных»</li><li>Федерального закона от 27.07.2006 № 149-ФЗ «Об информации, информационных технологиях и о защите информации»</li><li>Кодекса Российской Федерации об административных правонарушениях (ст. 14.3, 13.11)</li></ul><h2 id="_9-контактная-информация" tabindex="-1">9. Контактная информация <a class="header-anchor" href="#_9-контактная-информация" aria-label="Permalink to &quot;9. Контактная информация&quot;">​</a></h2><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p>',51)])])}const c=r(o,[["render",i]]);export{_ as __pageData,c as default};
